test('real workbench aliases select filter and water coil schemas', () => {
  for (const type of ['primary','medium','high','primary-filter','medium-filter','high-filter']) assert(field(F.read({ type }), 'efficiency'), type);
  for (const type of ['coil','heat','cooling-coil','heating-coil']) { const data = F.read({ type }); assert(field(data,'waterFlow'), type); assert(!field(data,'powerSupply'), type); }
});
test('electric heat remains separate from water coil and structural sections', () => { const data = F.read({ type: 'electric-heater' }); assert(field(data,'powerSupply')); assert(field(data,'stages')); assert(!field(data,'waterFlow')); for (const type of ['fresh','return','mix','supply','exhaust','access','empty','equalizer','eliminator']) { const s = F.read({ type }); assert(field(s,'description'), type); assert(!field(s,'capacity'), type); } });
test('nested professional filter arrangement supplies quantity with professional provenance', () => { const segment = { type:'primary', interface:{ selection:{professionalResult:{selector:'filter',model:'G3',result:{filterType:{name:'G3',detail:'GB/T'},arrangement:{total:4,specifications:[{code:'66',count:4}]}}}},output:{manual:{quantity:2,initialResistance:0}} } }; const data=F.read(segment); assert.equal(field(data,'quantity').value,4); assert.equal(field(data,'quantity').source,'professional'); assert.equal(field(data,'initialResistance').value,0); assert.equal(field(data,'initialResistance').source,'manual'); });
