test('multi-specification professional filters show every specification instead of a first-item scalar', () => { const segment={type:'primary',interface:{selection:{professionalResult:{selector:'filter',model:'G3',result:{filterType:{name:'G3'},arrangement:{total:3,specifications:[{code:'66',width:600,height:600,depth:50,count:2},{code:'36',width:300,height:600,depth:85,count:1}]}}}}}};const data=F.read(segment);assert.notEqual(field(data,'faceWidth').value,600);assert.notEqual(field(data,'faceDepth').value,50);const html=F.render(segment,esc);for(const value of ['66','36','300','85'])assert(html.includes(value),value); });
