function confirmBound(f) {
  if(!f.grid.innerHTML)f.ctx.actualRenderInputs();
  const event={target:f.confirm,currentTarget:f.confirm,preventDefault(){this.prevented=true;},stopImmediatePropagation(){this.stopped=true;}};
  const replacement=source.match(/replacePrototypeAction\('confirmSegment',\s*([A-Za-z_$][\w$]*)\)/);if(replacement){vm.runInContext(declaration(replacement[1]),f.ctx);return f.ctx[replacement[1]](event);}
  const guards=[];for(const match of source.matchAll(/\$\('confirmSegment'\)\.addEventListener\('click',\s*(?:(event|e)\s*=>|([A-Za-z_$][\w$]*))/g)){const name=match[2]||`actualConfirmGuard${guards.length}`;if(match[2])vm.runInContext(declaration(name),f.ctx);else{const open=source.indexOf('{',match.index),body=blockAt(open);assert(/^\s*,\s*true\s*\)/.test(source.slice(open+body.length)),'new confirm guard must run in capture phase');vm.runInContext(`function ${name}(${match[1]}) ${body}`,f.ctx);}guards.push(f.ctx[name]);}
  for(const guard of guards){guard(event);if(event.stopped)return;}
  const start=htmlSource.indexOf("$('confirmSegment').addEventListener('click',()=>{");assert(start>=0,'actual bound confirmation handler exists');vm.runInContext(`function actualConfirmSegment() ${blockAt(htmlSource.indexOf('{',start),htmlSource)}`,f.ctx);return f.ctx.actualConfirmSegment();
}
