test('recovery core fields and ranges match actual Phase1 engineering requirements',()=>{for(const key of ['form','efficiencyType']){assert(field(F.read({type:'heat-recovery'}),key),key);assert.equal(F.validateManualField({type:'heat-recovery'},key,'').valid,false,key);}for(const key of ['supplyAirflow','exhaustAirflow'])for(const value of ['0','-1'])assert.equal(F.validateManualField({type:'heat-recovery'},key,value).valid,false,`${key}:${value}`);for(const key of ['supplyResistance','exhaustResistance']){assert.equal(F.validateManualField({type:'heat-recovery'},key,'-1').valid,false);assert.equal(F.validateManualField({type:'heat-recovery'},key,'0').valid,true);}});
test('real filter code-count result preserves every specification and marks absent dimensions missing',()=>{const segment={type:'primary',interface:{selection:{professionalResult:{selector:'filter',model:'G3',result:{filterType:{name:'G3',detail:'初效'},arrangement:{total:3,specifications:[{code:'66',count:2},{code:'36',count:1}]}}}}}},data=F.read(segment);assert.equal(field(data,'quantity').value,3);for(const key of ['faceWidth','faceHeight','faceDepth']){assert.equal(field(data,key).value,'');assert.equal(field(data,key).source,'missing');}const rendered=F.render(segment,esc);assert(rendered.includes('66'));assert(rendered.includes('36'));assert(field(data,'specifications').value.includes('2'));assert(field(data,'specifications').value.includes('1'));});
test('actual recovery confirmation rejects missing form or efficiency type and accepts complete data',()=>{const complete={model:'REC',form:'板式',efficiencyType:'显热',supplyAirflow:1000,exhaustAirflow:900,supplyResistance:0,exhaustResistance:0,efficiency:65};for(const missing of ['form','efficiencyType',null]){const manual={...complete};if(missing)delete manual[missing];const f=uiFixture({id:'seg',type:'heat-recovery',name:'热回收',source:'厂家报告',length:800,confirmed:false,interface:{output:{manual}}});confirmBound(f);assert.equal(f.ctx.segments[0].confirmed,!missing,missing||'complete');assert.equal(f.saves,0);}});
(async()=>{let failed=0;for(const t of tests){try{await t.run();console.log(`PASS ${t.name}`);}catch(error){failed++;console.error(`FAIL ${t.name}\n${error.stack}`);}}console.log(`Segment field checks: ${tests.length} actual module/UI behavior cases; ${tests.length-failed} passed, ${failed} failed. Mock DOM/store; no browser visual test.`);if(failed)process.exitCode=1;})();
